package com.acme.harbor.client.rest

import com.acme.harbor.client.generated.coverprovider.QuotesApi
import com.acme.harbor.client.generated.coverprovider.model.QuoteRequest
import com.acme.harbor.enums.ProductGroup
import org.springframework.beans.factory.annotation.Value
import org.springframework.stereotype.Component
import org.springframework.web.client.RestClient
import java.math.BigDecimal
import java.time.Instant
import java.time.YearMonth

/**
 * Thin wrapper around the external cover-provider (`POST /quotes`).
 *
 * `QuotesApi`, `QuoteRequest` and `QuoteResponse` are generated by openapi-generator from
 * `api/cover-provider.yaml` into package `com.acme.harbor.client.generated.coverprovider` (not committed).
 */
@Component
class CoverProviderClient(
    restClientBuilder: RestClient.Builder,
    @Value("\${harbor.external.cover-provider.base-url}") baseUrl: String,
) {
    private val api = QuotesApi(restClientBuilder.baseUrl(baseUrl).build())

    data class Quote(val providerRef: String, val premium: BigDecimal, val premiumRate: BigDecimal, val validUntil: Instant)

    fun requestQuote(
        clientRef: String,
        productGroup: ProductGroup,
        subProducts: List<String>,
        uncoveredValue: BigDecimal,
        targetCoveredShare: BigDecimal?,
        fromPeriod: YearMonth,
        toPeriod: YearMonth,
    ): Quote {
        val response = api.createQuote(
            QuoteRequest(
                clientRef = clientRef,
                productGroup = QuoteRequest.ProductGroup.valueOf(productGroup.wireValue),
                subProducts = subProducts,
                uncoveredValue = uncoveredValue,
                targetCoveredShare = targetCoveredShare,
                fromPeriod = fromPeriod.toString(),
                toPeriod = toPeriod.toString(),
            ),
        )
        return Quote(response.providerRef, response.premium, response.premiumRate, response.validUntil.toInstant())
    }
}
